"use strict";
/* Fix Pack SB-3 (F-052): seller-tools (pr_*) strings, split out of
 * bundle-shared. Loaded ONLY by seller-tools pages, AFTER bundle-shared
 * and BEFORE their page bundle; merges into the shared I18N dict so
 * the in-place language switcher keeps working for pr_* strings. */
window.__PR_I18N = {en:{pr_title:"Property & neighbourhood report",pr_sub:"Enter a BC postal code for a neighbourhood snapshot from the {censusYear} Census, the nearest schools and — in Vancouver — reported-crime context. Add a full Vancouver address to also see the property's public assessment record and recent building permits. Each section names its source; school distances are approximate straight-line measurements.",pr_jump:"Property & neighbourhood report",pr_jump_sub:"census snapshot, nearby schools and the public property record for a BC address.",pr_postal:"Postal code",pr_postal_ph:"e.g. V6B 1A1",pr_optional:"(optional — adds the property record)",pr_btn:"Build my report",pr_loading:"Building your report…",pr_err:"The report could not be built right now. Please try again in a moment.",pr_err_rate:"Too many reports requested — please wait a minute and try again.",pr_err_postal:"Please enter a valid Canadian postal code.",pr_out_area:"This report covers British Columbia only. The postal code entered is outside BC, so no report was built.",pr_hood_title:"Neighbourhood snapshot — {fsa}",pr_src_census:"Source: Statistics Canada, {censusYear} Census Profile (forward sortation area {fsa}); income is for {incomeYear}.",pr_pop:"Population ({censusYear})",pr_dwell:"Occupied homes",pr_income:"Median household income ({incomeYear})",pr_hhsize:"Average household size",pr_medage:"Median age",pr_age_child:"Residents under 15",pr_age_senior:"Residents 65 and over",pr_owner:"Homeowners",pr_renter:"Renters",pr_detached:"Single-detached homes",pr_eng_home:"English spoken most often at home",pr_nonoff_home:"A non-official language spoken most often at home",pr_schools_title:"Nearest schools",pr_schools_src:"Source: BC Ministry of Education open data, {schoolYear}. Distances are straight-line from the area centre; school catchments are set by the district — confirm eligibility with them.",pr_school_e:"Elementary",pr_school_s:"Secondary",pr_school_m:"Middle",pr_school_b:"Elementary & secondary",pr_school_pub:"Public",pr_school_ind:"Independent",pr_safety_title:"Safety — reported crime",pr_safety_body:"{n} incidents were reported in {area} in {year} — {total} across Vancouver's listed neighbourhoods. These are police-reported incidents, not a safety rating.",pr_safety_src:"Source: Vancouver Police Department open data.",pr_safety_na:"Reported-crime data is published at neighbourhood level only for Vancouver, so it is not available for this area.",pr_card_title:"Property record — {addr}",pr_card_land:"Land",pr_card_building:"Building",pr_card_total:"Total assessed value ({year})",pr_card_built:"Year built",pr_card_pid:"PID",pr_card_zoning:"Zoning",pr_card_levy:"Property tax levy",pr_card_note:"Assessed value is the figure used for property taxes — it is not a market value or an asking price. All figures are in Canadian dollars.",pr_card_strata:"This address is a strata building with {n} units in the public record, and assessed values vary by unit — so the range across the building is shown. Your own unit's exact figure is on BC Assessment (link below).",pr_card_range:"Assessed values across the building's units",pr_card_src:"Source: City of Vancouver open data (property tax report & issued building permits).",pr_permits_title:"Recent building permits",pr_permits_none:"No permits were found for this address in the City of Vancouver open data.",pr_prop_na:"Live property records are available for Vancouver addresses. For other BC cities, use the official records below — BC Assessment holds the assessed value of every BC property.",pr_prop_notfound:"This address could not be matched in the City of Vancouver open data. Check the address, or look the property up on BC Assessment below.",pr_links_title:"Official records",pr_link_bca:"BC Assessment — look up any BC property",pr_link_parcel:"ParcelMap BC — parcel boundaries & legal description",pr_link_walkscore:"Walk Score — walkability at this address",pr_link_ltsa:"LTSA — land title records & searches",pr_est_title:"What might it be worth?",pr_est_body:"Assessment is not market value. Get a free estimate range from comparable homes currently listed — the same tool our sellers use, above.",pr_est_btn:"Estimate this home's value",pr_gated_note:"Two things cannot be shown yet. Sold prices are MLS® data, restricted to licensed professionals; title details (owner, mortgages, liens and other charges) live only on the LTSA title record. Both sections below are built; each becomes available only when its own data arrangement is in place — until then they say exactly what is missing and where the official record lives.",pr_sold_title:"Sold history",pr_sold_gated:"Not available yet. Showing sold prices requires licensing and a board data agreement, which are not in place yet.",pr_title_title:"Title & lien check",pr_title_gated:"Not available yet. A title search shows the registered owner, mortgages, liens, easements and other charges on a property. Ordering through this site is not set up yet — you can order a search yourself from the BC Land Title and Survey Authority (LTSA) today for a registry fee.",pr_title_btn:"How to get a title search",pr_title_sent:"No order was placed — title-search ordering is not available on this site yet. You can order a search yourself today from the LTSA — a title is a public record (see Official records above).",pr_area:"Area",pr_schools_none:"No schools were found within 10 km of this area in the provincial open data.",pr_err_city:"Please choose the city for the address.",pr_prop_unavailable:"The property record could not be loaded right now. Please try again in a moment.",pr_prop_ambiguous:"More than one property in the public record matches this address, so none is shown rather than guessing. BC Assessment (below) holds the exact record for your unit or lot.",pr_census_na:"Census figures aren't available for this postal area.",pr_schools_unavailable:"School information could not be loaded right now — please try again in a moment.",pr_safety_unavailable:"Reported-crime information could not be loaded right now — please try again in a moment.",pr_permits_unavailable:"Permit information could not be loaded right now — please try again in a moment.",pr_card_median:"Median assessed value across the building's units ({year})",pr_card_truncated:"The public record for this building is too large to read in full here, so no range is shown rather than a partial one. Your own unit's exact figure is on BC Assessment (link below).",pr_km:"km",pr_school_other:"Other",pr_approx:"The location match is approximate, so the figures below are for the nearest matching area.",pr_title_placed:"Your title-search request has been placed.",pr_title_unavailable:"Title-search ordering is not available yet — no order was placed. You can order a search yourself from the LTSA (see Official records above).",pr_render_err:"The report was received but could not be displayed. Please reload the page and try again.",pr_title_err:"The title-search request could not be completed — please try again.",pr_gated_pending:"This section is not available yet.",pr_privacy:"Privacy: what you enter here is handled as follows. (1) Home valuation: your name, property address, city, phone, email and the property details you give (type, bedrooms, bathrooms, floor area) are stored in this site's lead database so Erfan can prepare your asking-price range and contact you about it. They are kept until you ask for their deletion or Erfan removes them, and they are never sold. To delete them, send the same email and property address you submitted through the deletion form at the bottom of this page (or ask Erfan directly) — deletion is permanent. (2) Property report: the postal code and address you enter are sent to this site's server, which passes them to public data services (OpenStreetMap and the City of Vancouver open data) to build the report. The text you type is not kept; the map location found for it is cached, under a coded key rather than the address itself, for up to 30 days so repeat lookups are faster.",pr_gated_note_live:"Sold prices come from MLS® records, available to licensed professionals; title details (owner, mortgages, liens and other charges) come from the LTSA title record. The two sections below draw on those official records for Erfan's clients.",pr_sold_live:"The sold history for this property is available to Erfan's clients — ask him for the full MLS® sold record, including dates and prices.",pr_title_live:"A title search shows the registered owner, mortgages, liens, easements and other charges on a property. Clients can order a title search through Erfan, or directly from the BC Land Title and Survey Authority (LTSA) for a registry fee (see the Official records section).",pr_city_note:"The property record covers Vancouver addresses; other cities get the official record links."},fa:{pr_title:"گزارش ملک و محله",pr_sub:"یک کد پستیِ بریتیش کلمبیا وارد کنید تا نمایی از محله بر اساس سرشماری {censusYear}، نزدیک‌ترین مدرسه‌ها و — در ونکوور — آمار جرم گزارش‌شده ببینید. اگر نشانی کاملِ یک ملک در ونکوور را هم اضافه کنید، سابقه‌ی عمومی ارزیابی ملک و پروانه‌های ساختمانی اخیر آن هم نشان داده می‌شود. هر بخش منبعش را نام می‌برد؛ فاصله‌ی مدرسه‌ها اندازه‌گیری تقریبیِ خط مستقیم است.",pr_jump:"گزارش ملک و محله",pr_jump_sub:"نمای سرشماری، مدرسه‌های نزدیک و سابقه‌ی عمومی ملک برای یک نشانی در بریتیش کلمبیا.",pr_postal:"کد پستی",pr_postal_ph:"مثلاً V6B 1A1",pr_optional:"(اختیاری — سابقه‌ی ملک را اضافه می‌کند)",pr_btn:"گزارشم را بساز",pr_loading:"در حال ساختن گزارش…",pr_err:"در حال حاضر ساختن گزارش ممکن نشد. لطفاً چند لحظه دیگر دوباره تلاش کنید.",pr_err_rate:"تعداد گزارش‌ها زیاد شده است — لطفاً یک دقیقه صبر کنید و دوباره تلاش کنید.",pr_err_postal:"لطفاً یک کد پستی معتبر کانادایی وارد کنید.",pr_out_area:"این گزارش فقط بریتیش کلمبیا را پوشش می‌دهد. کد پستی واردشده بیرون از بریتیش کلمبیاست، پس گزارشی ساخته نشد.",pr_hood_title:"نمای محله — {fsa}",pr_src_census:"منبع: اداره‌ی آمار کانادا، پرونده‌ی سرشماری {censusYear} (ناحیه‌ی سه‌حرفی کد پستی {fsa})؛ درآمد مربوط به سال {incomeYear} است.",pr_pop:"جمعیت ({censusYear})",pr_dwell:"خانه‌های مسکونی",pr_income:"درآمد میانه‌ی خانوار ({incomeYear})",pr_hhsize:"میانگین اندازه‌ی خانوار",pr_medage:"سن میانه",pr_age_child:"ساکنان زیر ۱۵ سال",pr_age_senior:"ساکنان ۶۵ سال و بالاتر",pr_owner:"مالکان خانه",pr_renter:"مستأجران",pr_detached:"خانه‌های مستقل تک‌خانواری",pr_eng_home:"انگلیسی، پرکاربردترین زبان در خانه",pr_nonoff_home:"یک زبان غیررسمی، پرکاربردترین زبان در خانه",pr_schools_title:"نزدیک‌ترین مدرسه‌ها",pr_schools_src:"منبع: داده‌های باز وزارت آموزش بریتیش کلمبیا، سال تحصیلی {schoolYear}. فاصله‌ها خط مستقیم از مرکز ناحیه‌اند؛ محدوده‌ی ثبت‌نام را منطقه‌ی آموزشی تعیین می‌کند — واجد شرایط بودن را از خودشان بپرسید.",pr_school_e:"ابتدایی",pr_school_s:"متوسطه",pr_school_m:"راهنمایی",pr_school_b:"ابتدایی و متوسطه",pr_school_pub:"دولتی",pr_school_ind:"غیردولتی",pr_safety_title:"امنیت — جرم گزارش‌شده",pr_safety_body:"در سال {year} در {area} تعداد {n} رویداد گزارش شد — در محله‌های فهرست‌شده‌ی ونکوور در مجموع {total} رویداد. این‌ها رویدادهای گزارش‌شده به پلیس‌اند، نه امتیاز امنیت.",pr_safety_src:"منبع: داده‌های باز پلیس ونکوور.",pr_safety_na:"داده‌ی جرم در سطح محله فقط برای ونکوور منتشر می‌شود، پس برای این ناحیه در دسترس نیست.",pr_card_title:"سابقه‌ی ملک — {addr}",pr_card_land:"زمین",pr_card_building:"ساختمان",pr_card_total:"ارزش کل ارزیابی‌شده ({year})",pr_card_built:"سال ساخت",pr_card_pid:"PID",pr_card_zoning:"کاربری (زونینگ)",pr_card_levy:"مالیات ملک",pr_card_note:"ارزش ارزیابی‌شده عددی است که مالیات ملک بر پایه‌ی آن حساب می‌شود — نه ارزش بازار است و نه قیمت فروش. همه‌ی عددها به دلار کاناداست.",pr_card_strata:"این نشانی یک ساختمان اشتراکی (استراتا) با {n} واحد در سوابق عمومی است و ارزش ارزیابی هر واحد فرق می‌کند — پس بازه‌ی کل ساختمان نشان داده شده است. عدد دقیق واحد خودتان در سایت BC Assessment است (پیوند پایین).",pr_card_range:"بازه‌ی ارزش ارزیابی واحدهای ساختمان",pr_card_src:"منبع: داده‌های باز شهر ونکوور (گزارش مالیات ملک و پروانه‌های ساختمانی صادرشده).",pr_permits_title:"پروانه‌های ساختمانی اخیر",pr_permits_none:"برای این نشانی در داده‌های باز شهر ونکوور پروانه‌ای پیدا نشد.",pr_prop_na:"سوابق زنده‌ی ملک برای نشانی‌های ونکوور در دسترس است. برای شهرهای دیگر بریتیش کلمبیا از سوابق رسمی پایین استفاده کنید — ارزش ارزیابی هر ملک در بریتیش کلمبیا نزد BC Assessment است.",pr_prop_notfound:"این نشانی در داده‌های باز شهر ونکوور پیدا نشد. نشانی را بررسی کنید، یا ملک را در BC Assessment (پایین) جستجو کنید.",pr_links_title:"سوابق رسمی",pr_link_bca:"BC Assessment — جستجوی هر ملک در بریتیش کلمبیا",pr_link_parcel:"ParcelMap BC — مرز قطعه‌ها و شرح قانونی",pr_link_walkscore:"Walk Score — قابلیت پیاده‌روی این نشانی",pr_link_ltsa:"LTSA — سوابق و جستجوی سند مالکیت",pr_est_title:"ارزشش چقدر می‌تواند باشد؟",pr_est_body:"ارزش ارزیابی با ارزش بازار یکی نیست. یک بازه‌ی تخمینی رایگان از روی خانه‌های مشابهی که همین حالا برای فروش فهرست شده‌اند بگیرید — همان ابزار فروشندگان ما، در بالا.",pr_est_btn:"ارزش این خانه را تخمین بزن",pr_gated_note:"دو چیز را هنوز نمی‌شود نشان داد. قیمت‌های فروش قطعی داده‌ی MLS® است و فقط در اختیار متخصصان دارای مجوز است؛ جزئیات سند (مالک، وام مسکن، رهن و سایر حقوق ثبت‌شده) فقط روی سند مالکیت در LTSA است. هر دو بخش زیر ساخته شده‌اند و هرکدام فقط وقتی ترتیبات داده‌ی خودش برقرار شود در دسترس می‌شود — تا آن زمان دقیقاً می‌گویند چه چیزی کم است و سابقه‌ی رسمی کجاست.",pr_sold_title:"سابقه‌ی فروش",pr_sold_gated:"هنوز در دسترس نیست. نمایش قیمت‌های فروش به مجوز و قرارداد داده با بورد نیاز دارد که هنوز برقرار نشده‌اند.",pr_title_title:"بررسی سند و رهن",pr_title_gated:"هنوز در دسترس نیست. جستجوی سند، مالک ثبت‌شده، وام‌های مسکن، رهن‌ها، حق عبورها و سایر حقوق ثبت‌شده روی یک ملک را نشان می‌دهد. سفارش از راه این سایت هنوز راه نیفتاده است — همین امروز می‌توانید خودتان از اداره‌ی ثبت اسناد بریتیش کلمبیا (LTSA) با هزینه‌ی ثبت سفارش بدهید.",pr_title_btn:"نحوه‌ی دریافت جستجوی سند",pr_title_sent:"هیچ سفارشی ثبت نشد — سفارش جستجوی سند هنوز در این سایت در دسترس نیست. همین امروز می‌توانید خودتان از LTSA سفارش بدهید — سند مالکیت یک سابقه‌ی عمومی است (بخش سوابق رسمی در بالا را ببینید).",pr_area:"ناحیه",pr_schools_none:"در داده‌های باز استان، در شعاع ۱۰ کیلومتری این ناحیه مدرسه‌ای پیدا نشد.",pr_err_city:"لطفاً شهرِ نشانی را انتخاب کنید.",pr_prop_unavailable:"در حال حاضر بارگذاری سابقه‌ی ملک ممکن نشد. لطفاً چند لحظه دیگر دوباره تلاش کنید.",pr_prop_ambiguous:"در سوابق عمومی بیش از یک ملک با این نشانی مطابقت دارد، پس برای پرهیز از حدس هیچ‌کدام نشان داده نمی‌شود. سابقه‌ی دقیق واحد یا قطعه‌ی شما نزد BC Assessment است (پایین).",pr_census_na:"عددهای سرشماری برای این ناحیه‌ی پستی در دسترس نیست.",pr_schools_unavailable:"در حال حاضر بارگذاری اطلاعات مدرسه‌ها ممکن نشد — لطفاً چند لحظه دیگر دوباره تلاش کنید.",pr_safety_unavailable:"در حال حاضر بارگذاری آمار جرم گزارش‌شده ممکن نشد — لطفاً چند لحظه دیگر دوباره تلاش کنید.",pr_permits_unavailable:"در حال حاضر بارگذاری اطلاعات پروانه‌ها ممکن نشد — لطفاً چند لحظه دیگر دوباره تلاش کنید.",pr_card_median:"ارزش میانه‌ی ارزیابی‌شده در میان واحدهای ساختمان ({year})",pr_card_truncated:"سابقه‌ی عمومی این ساختمان آن‌قدر بزرگ است که اینجا کامل خوانده نمی‌شود، پس به‌جای یک بازه‌ی ناقص، هیچ بازه‌ای نشان داده نمی‌شود. عدد دقیق واحد خودتان در BC Assessment است (پیوند پایین).",pr_km:"کیلومتر",pr_school_other:"سایر",pr_approx:"تطبیق مکان تقریبی است، پس عددهای زیر مربوط به نزدیک‌ترین ناحیه‌ی منطبق‌اند.",pr_title_placed:"درخواست جستجوی سند شما ثبت شد.",pr_title_unavailable:"سفارش جستجوی سند هنوز در دسترس نیست — هیچ سفارشی ثبت نشد. همین امروز می‌توانید خودتان از LTSA سفارش بدهید (سوابق رسمی در بالا را ببینید).",pr_render_err:"گزارش دریافت شد اما نمایش داده نشد. لطفاً صفحه را دوباره بارگذاری کنید و دوباره تلاش کنید.",pr_title_err:"درخواست جستجوی سند کامل نشد — لطفاً دوباره تلاش کنید.",pr_gated_pending:"این بخش هنوز در دسترس نیست.",pr_privacy:"حریم خصوصی: آنچه اینجا وارد می‌کنید این‌گونه مدیریت می‌شود. (۱) ارزیابی خانه: نام، نشانی ملک، شهر، تلفن، ایمیل و جزئیات ملکی که می‌دهید (نوع، تعداد اتاق‌خواب و حمام، متراژ) در پایگاه داده‌ی سرنخ‌های این سایت ذخیره می‌شود تا عرفان بازه‌ی قیمت درخواستی‌تان را آماده کند و درباره‌اش با شما تماس بگیرد. این اطلاعات تا وقتی نگه داشته می‌شود که خودتان حذفشان را بخواهید یا عرفان حذفشان کند، و هرگز فروخته نمی‌شود. برای حذف، همان ایمیل و نشانی ملکی را که ثبت کرده‌اید از طریق فرم حذف پایین همین صفحه بفرستید (یا مستقیم از عرفان بخواهید) — حذف دائمی است. (۲) گزارش ملک: کد پستی و نشانی‌ای که وارد می‌کنید به سرور این سایت فرستاده می‌شود و سرور آن‌ها را برای ساختن گزارش به سرویس‌های داده‌ی عمومی (OpenStreetMap و داده‌های باز شهر ونکوور) می‌دهد. متنی که تایپ می‌کنید نگه داشته نمی‌شود؛ موقعیت نقشه‌ای که برایش پیدا می‌شود، با یک کلید رمزی به‌جای خود نشانی، تا ۳۰ روز نگه داشته می‌شود تا جستجوهای تکراری سریع‌تر شوند.",pr_gated_note_live:"قیمت‌های فروش قطعی از سوابق MLS® می‌آید که در اختیار متخصصان دارای مجوز است؛ جزئیات سند (مالک، وام مسکن، رهن و سایر حقوق ثبت‌شده) از سند مالکیت در LTSA می‌آید. دو بخش زیر برای مشتریان عرفان بر پایه‌ی همین سوابق رسمی کار می‌کنند.",pr_sold_live:"سابقه‌ی فروش این ملک برای مشتریان عرفان در دسترس است — سابقه‌ی کامل فروش MLS® شامل تاریخ و قیمت را از او بخواهید.",pr_title_live:"جستجوی سند، مالک ثبت‌شده، وام‌های مسکن، رهن‌ها، حق عبورها و سایر حقوق ثبت‌شده روی یک ملک را نشان می‌دهد. مشتریان می‌توانند جستجوی سند را از راه عرفان سفارش دهند، یا مستقیم از اداره‌ی ثبت اسناد بریتیش کلمبیا (LTSA) با هزینه‌ی ثبت (بخش سوابق رسمی را ببینید).",pr_city_note:"سابقه‌ی ملک نشانی‌های ونکوور را پوشش می‌دهد؛ شهرهای دیگر پیوند سوابق رسمی را می‌گیرند."},hi:{pr_title:"संपत्ति और पड़ोस रिपोर्ट",pr_sub:"{censusYear} की जनगणना से पड़ोस की झलक, निकटतम स्कूल और — वैंकूवर में — दर्ज अपराध का संदर्भ पाने के लिए BC का डाक कोड दर्ज करें। वैंकूवर का पूरा पता जोड़ने पर संपत्ति का सार्वजनिक मूल्यांकन रिकॉर्ड और हाल के भवन परमिट भी दिखेंगे। हर खंड का स्रोत दिया गया है; स्कूलों की दूरियाँ अनुमानित सीधी-रेखा माप हैं।",pr_jump:"संपत्ति और पड़ोस रिपोर्ट",pr_jump_sub:"जनगणना झलक, निकट के स्कूल और BC के पते का सार्वजनिक संपत्ति रिकॉर्ड।",pr_postal:"डाक कोड",pr_postal_ph:"जैसे V6B 1A1",pr_optional:"(वैकल्पिक — संपत्ति रिकॉर्ड जोड़ता है)",pr_btn:"मेरी रिपोर्ट बनाएँ",pr_loading:"आपकी रिपोर्ट बन रही है…",pr_err:"अभी रिपोर्ट नहीं बन सकी। कृपया थोड़ी देर में फिर प्रयास करें।",pr_err_rate:"बहुत ज़्यादा रिपोर्ट अनुरोध हैं — कृपया एक मिनट प्रतीक्षा करके फिर प्रयास करें।",pr_err_postal:"कृपया एक मान्य कनाडाई डाक कोड दर्ज करें।",pr_out_area:"यह रिपोर्ट केवल ब्रिटिश कोलंबिया के लिए है। दर्ज किया गया डाक कोड BC से बाहर का है, इसलिए कोई रिपोर्ट नहीं बनी।",pr_hood_title:"पड़ोस की झलक — {fsa}",pr_src_census:"स्रोत: सांख्यिकी कनाडा, {censusYear} जनगणना प्रोफ़ाइल (फ़ॉरवर्ड सॉर्टेशन क्षेत्र {fsa}); आय {incomeYear} की है।",pr_pop:"जनसंख्या ({censusYear})",pr_dwell:"कब्ज़े वाले घर",pr_income:"मध्यिका घरेलू आय ({incomeYear})",pr_hhsize:"औसत परिवार आकार",pr_medage:"मध्यिका आयु",pr_age_child:"15 वर्ष से कम निवासी",pr_age_senior:"65 वर्ष और अधिक के निवासी",pr_owner:"घर के मालिक",pr_renter:"किरायेदार",pr_detached:"एकल-अलग घर",pr_eng_home:"घर पर सबसे अधिक बोली जाने वाली अंग्रेज़ी",pr_nonoff_home:"घर पर सबसे अधिक बोली जाने वाली कोई गैर-आधिकारिक भाषा",pr_schools_title:"निकटतम स्कूल",pr_schools_src:"स्रोत: BC शिक्षा मंत्रालय का खुला डेटा, {schoolYear}। दूरियाँ क्षेत्र के केंद्र से सीधी रेखा में हैं; स्कूल क्षेत्र ज़िला तय करता है — उनसे पात्रता की पुष्टि करें।",pr_school_e:"प्राथमिक",pr_school_s:"माध्यमिक",pr_school_m:"मध्य विद्यालय",pr_school_b:"प्राथमिक और माध्यमिक",pr_school_pub:"सार्वजनिक",pr_school_ind:"स्वतंत्र",pr_safety_title:"सुरक्षा — दर्ज अपराध",pr_safety_body:"{year} में {area} में {n} घटनाएँ दर्ज हुईं — वैंकूवर के सूचीबद्ध पड़ोसों में कुल {total}। ये पुलिस में दर्ज घटनाएँ हैं, सुरक्षा रेटिंग नहीं।",pr_safety_src:"स्रोत: वैंकूवर पुलिस विभाग का खुला डेटा।",pr_safety_na:"दर्ज अपराध का डेटा पड़ोस स्तर पर केवल वैंकूवर के लिए प्रकाशित होता है, इसलिए इस क्षेत्र के लिए उपलब्ध नहीं है।",pr_card_title:"संपत्ति रिकॉर्ड — {addr}",pr_card_land:"भूमि",pr_card_building:"भवन",pr_card_total:"कुल मूल्यांकित मूल्य ({year})",pr_card_built:"निर्माण वर्ष",pr_card_pid:"PID",pr_card_zoning:"ज़ोनिंग",pr_card_levy:"संपत्ति कर लेवी",pr_card_note:"मूल्यांकित मूल्य वह आंकड़ा है जिससे संपत्ति कर तय होता है — यह न बाज़ार मूल्य है, न मांगी गई कीमत। सभी आंकड़े कनाडाई डॉलर में हैं।",pr_card_strata:"यह पता सार्वजनिक रिकॉर्ड में {n} इकाइयों वाली एक स्ट्राटा इमारत है, और हर इकाई का मूल्यांकित मूल्य अलग होता है — इसलिए पूरी इमारत की सीमा दिखाई गई है। आपकी इकाई का सटीक आंकड़ा BC Assessment पर है (नीचे लिंक)।",pr_card_range:"इमारत की इकाइयों के मूल्यांकित मूल्यों की सीमा",pr_card_src:"स्रोत: वैंकूवर शहर का खुला डेटा (संपत्ति कर रिपोर्ट और जारी भवन परमिट)।",pr_permits_title:"हाल के भवन परमिट",pr_permits_none:"वैंकूवर शहर के खुले डेटा में इस पते के लिए कोई परमिट नहीं मिला।",pr_prop_na:"लाइव संपत्ति रिकॉर्ड वैंकूवर के पतों के लिए उपलब्ध हैं। BC के अन्य शहरों के लिए नीचे दिए आधिकारिक रिकॉर्ड उपयोग करें — हर BC संपत्ति का मूल्यांकित मूल्य BC Assessment के पास है।",pr_prop_notfound:"यह पता वैंकूवर शहर के खुले डेटा में मेल नहीं खा सका। पता जांचें, या नीचे BC Assessment पर संपत्ति खोजें।",pr_links_title:"आधिकारिक रिकॉर्ड",pr_link_bca:"BC Assessment — कोई भी BC संपत्ति खोजें",pr_link_parcel:"ParcelMap BC — पार्सल सीमाएँ और कानूनी विवरण",pr_link_walkscore:"Walk Score — इस पते पर पैदल चलने की सुविधा",pr_link_ltsa:"LTSA — भूमि स्वामित्व रिकॉर्ड और खोज",pr_est_title:"इसकी कीमत क्या हो सकती है?",pr_est_body:"मूल्यांकन बाज़ार मूल्य नहीं होता। अभी सूचीबद्ध तुलनीय घरों से मुफ़्त अनुमान-सीमा पाएँ — वही टूल जो हमारे विक्रेता उपयोग करते हैं, ऊपर दिया है।",pr_est_btn:"इस घर का मूल्य अनुमान करें",pr_gated_note:"दो चीज़ें अभी नहीं दिखाई जा सकतीं। बिक्री कीमतें MLS® डेटा हैं, जो केवल लाइसेंसधारी पेशेवरों के लिए हैं; स्वामित्व विवरण (मालिक, बंधक, ग्रहणाधिकार और अन्य भार) केवल LTSA के स्वामित्व रिकॉर्ड पर हैं। नीचे के दोनों खंड बने हुए हैं; प्रत्येक तभी उपलब्ध होगा जब उसकी अपनी डेटा व्यवस्था तैयार हो जाएगी — तब तक वे ठीक-ठीक बताते हैं कि क्या कमी है और आधिकारिक रिकॉर्ड कहाँ है।",pr_sold_title:"बिक्री इतिहास",pr_sold_gated:"अभी उपलब्ध नहीं है। बिक्री कीमतें दिखाने के लिए लाइसेंस और बोर्ड के साथ डेटा समझौता चाहिए, जो अभी तैयार नहीं हैं।",pr_title_title:"स्वामित्व और ग्रहणाधिकार जांच",pr_title_gated:"अभी उपलब्ध नहीं है। स्वामित्व खोज पंजीकृत मालिक, बंधक, ग्रहणाधिकार, सुविधाधिकार और संपत्ति पर अन्य भार दिखाती है। इस साइट से आदेश की व्यवस्था अभी नहीं है — आप आज ही BC भूमि स्वामित्व और सर्वेक्षण प्राधिकरण (LTSA) से रजिस्ट्री शुल्क पर स्वयं खोज मंगा सकते हैं।",pr_title_btn:"स्वामित्व खोज कैसे प्राप्त करें",pr_title_sent:"कोई आदेश नहीं दिया गया — इस साइट पर स्वामित्व खोज का आदेश अभी उपलब्ध नहीं है। आप आज ही LTSA से स्वयं खोज मंगा सकते हैं — स्वामित्व एक सार्वजनिक रिकॉर्ड है (ऊपर आधिकारिक रिकॉर्ड देखें)।",pr_area:"क्षेत्र",pr_schools_none:"प्रांतीय खुले डेटा में इस क्षेत्र से 10 किमी के भीतर कोई स्कूल नहीं मिला।",pr_err_city:"कृपया पते का शहर चुनें।",pr_prop_unavailable:"अभी संपत्ति रिकॉर्ड लोड नहीं हो सका। कृपया थोड़ी देर में फिर प्रयास करें।",pr_prop_ambiguous:"सार्वजनिक रिकॉर्ड में इस पते से एक से अधिक संपत्तियाँ मेल खाती हैं, इसलिए अनुमान लगाने के बजाय कोई भी नहीं दिखाई गई। आपकी इकाई या लॉट का सटीक रिकॉर्ड BC Assessment के पास है (नीचे)।",pr_census_na:"इस डाक क्षेत्र के लिए जनगणना के आंकड़े उपलब्ध नहीं हैं।",pr_schools_unavailable:"अभी स्कूलों की जानकारी लोड नहीं हो सकी — कृपया थोड़ी देर में फिर प्रयास करें।",pr_safety_unavailable:"अभी दर्ज अपराध की जानकारी लोड नहीं हो सकी — कृपया थोड़ी देर में फिर प्रयास करें।",pr_permits_unavailable:"अभी परमिट की जानकारी लोड नहीं हो सकी — कृपया थोड़ी देर में फिर प्रयास करें।",pr_card_median:"इमारत की इकाइयों में माध्य मूल्यांकित मूल्य ({year})",pr_card_truncated:"इस इमारत का सार्वजनिक रिकॉर्ड यहाँ पूरा पढ़ने के लिए बहुत बड़ा है, इसलिए आंशिक सीमा दिखाने के बजाय कोई सीमा नहीं दिखाई गई। आपकी इकाई का सटीक आंकड़ा BC Assessment पर है (नीचे लिंक)।",pr_km:"किमी",pr_school_other:"अन्य",pr_approx:"स्थान का मिलान अनुमानित है, इसलिए नीचे के आंकड़े निकटतम मेल खाने वाले क्षेत्र के हैं।",pr_title_placed:"आपका स्वामित्व खोज अनुरोध दर्ज कर दिया गया है।",pr_title_unavailable:"स्वामित्व खोज का आदेश अभी उपलब्ध नहीं है — कोई आदेश नहीं दिया गया। आप आज ही LTSA से स्वयं खोज मंगा सकते हैं (ऊपर आधिकारिक रिकॉर्ड देखें)।",pr_render_err:"रिपोर्ट प्राप्त हो गई थी लेकिन प्रदर्शित नहीं हो सकी। कृपया पेज को फिर से लोड करके पुनः प्रयास करें।",pr_title_err:"स्वामित्व खोज का अनुरोध पूरा नहीं हो सका — कृपया पुनः प्रयास करें।",pr_gated_pending:"यह खंड अभी उपलब्ध नहीं है।",pr_privacy:"गोपनीयता: आप यहाँ जो दर्ज करते हैं, उसका प्रबंधन इस प्रकार होता है। (1) गृह मूल्यांकन: आपका नाम, संपत्ति का पता, शहर, फ़ोन, ईमेल और आपके द्वारा दिए गए संपत्ति विवरण (प्रकार, बेडरूम, बाथरूम, क्षेत्रफल) इस साइट के लीड डेटाबेस में सहेजे जाते हैं ताकि एरफ़ान आपकी मांगी जाने वाली कीमत की सीमा तैयार कर सकें और उसी बारे में आपसे संपर्क कर सकें। इन्हें तब तक रखा जाता है जब तक आप इन्हें हटाने के लिए न कहें या एरफ़ान इन्हें हटा न दें, और इन्हें कभी बेचा नहीं जाता। इन्हें हटाने के लिए, वही ईमेल और संपत्ति का पता जो आपने जमा किया था, इस पृष्ठ के नीचे दिए गए हटाने वाले फ़ॉर्म के माध्यम से भेजें (या सीधे एरफ़ान से कहें) — हटाना स्थायी है। (2) संपत्ति रिपोर्ट: आप जो डाक कोड और पता दर्ज करते हैं, वे इस साइट के सर्वर को भेजे जाते हैं, जो रिपोर्ट बनाने के लिए उन्हें सार्वजनिक डेटा सेवाओं (OpenStreetMap और सिटी ऑफ़ वैंकूवर ओपन डेटा) को देता है। आप जो पाठ लिखते हैं वह रखा नहीं जाता; उसके लिए मिला मानचित्र स्थान, पते के बजाय एक कोडित कुंजी के तहत, 30 दिनों तक कैश किया जाता है ताकि दोबारा खोज तेज़ हो।",pr_gated_note_live:"बिक्री कीमतें MLS® रिकॉर्ड से आती हैं, जो लाइसेंसधारी पेशेवरों के लिए उपलब्ध हैं; स्वामित्व विवरण (मालिक, बंधक, ग्रहणाधिकार और अन्य भार) LTSA के स्वामित्व रिकॉर्ड से आते हैं। नीचे के दोनों खंड एरफ़ान के ग्राहकों के लिए इन्हीं आधिकारिक रिकॉर्ड पर काम करते हैं।",pr_sold_live:"इस प्रॉपर्टी का बिक्री इतिहास एरफ़ान के ग्राहकों के लिए उपलब्ध है — तारीखों और कीमतों सहित पूरा MLS® बिक्री रिकॉर्ड उनसे माँगें।",pr_title_live:"स्वामित्व खोज पंजीकृत मालिक, बंधक, ग्रहणाधिकार, सुविधाधिकार और संपत्ति पर अन्य भार दिखाती है। ग्राहक एरफ़ान के माध्यम से स्वामित्व खोज का आदेश दे सकते हैं, या रजिस्ट्री शुल्क पर सीधे BC भूमि स्वामित्व और सर्वेक्षण प्राधिकरण (LTSA) से (आधिकारिक रिकॉर्ड अनुभाग देखें)।",pr_city_note:"संपत्ति रिकॉर्ड वैंकूवर के पतों के लिए है; अन्य शहरों को आधिकारिक रिकॉर्ड के लिंक मिलते हैं।"},zh:{pr_title:"房产与社区报告",pr_sub:"输入 BC 省邮政编码，即可查看基于 {censusYear} 年人口普查的社区概况、最近的学校，以及（在温哥华）已报告犯罪的背景信息。再加上温哥华的完整地址，还可查看该房产的公开评估记录和近期建筑许可证。每个部分都注明来源；学校距离为近似直线距离。",pr_jump:"房产与社区报告",pr_jump_sub:"人口普查概况、附近学校，以及 BC 地址的公开房产记录。",pr_postal:"邮政编码",pr_postal_ph:"例如 V6B 1A1",pr_optional:"（可选 — 添加房产记录）",pr_btn:"生成我的报告",pr_loading:"正在生成报告…",pr_err:"目前无法生成报告。请稍后再试。",pr_err_rate:"报告请求过多——请等待一分钟后重试。",pr_err_postal:"请输入有效的加拿大邮政编码。",pr_out_area:"本报告仅覆盖不列颠哥伦比亚省。输入的邮政编码在 BC 省以外，因此未生成报告。",pr_hood_title:"社区概况 — {fsa}",pr_src_census:"来源：加拿大统计局 {censusYear} 年人口普查档案（邮政分拣区 {fsa}）；收入为 {incomeYear} 年数据。",pr_pop:"人口（{censusYear}）",pr_dwell:"已入住住宅",pr_income:"家庭收入中位数（{incomeYear}）",pr_hhsize:"平均家庭规模",pr_medage:"年龄中位数",pr_age_child:"15 岁以下居民",pr_age_senior:"65 岁及以上居民",pr_owner:"自有住房者",pr_renter:"租房者",pr_detached:"独立式住宅",pr_eng_home:"在家最常说英语",pr_nonoff_home:"在家最常说一种非官方语言",pr_schools_title:"最近的学校",pr_schools_src:"来源：BC 省教育厅开放数据，{schoolYear} 学年。距离为从区域中心出发的直线距离；学区划分由教育局决定——请向其确认入学资格。",pr_school_e:"小学",pr_school_s:"中学",pr_school_m:"初中",pr_school_b:"小学及中学",pr_school_pub:"公立",pr_school_ind:"独立学校",pr_safety_title:"安全 — 已报告犯罪",pr_safety_body:"{year} 年，{area} 共报告 {n} 起事件——温哥华各已列社区共 {total} 起。这些是向警方报告的事件，并非安全评级。",pr_safety_src:"来源：温哥华警察局开放数据。",pr_safety_na:"已报告犯罪数据仅按社区级别为温哥华发布，因此该地区暂无此数据。",pr_card_title:"房产记录 — {addr}",pr_card_land:"土地",pr_card_building:"建筑",pr_card_total:"评估总价（{year}）",pr_card_built:"建成年份",pr_card_pid:"PID",pr_card_zoning:"分区",pr_card_levy:"房产税",pr_card_note:"评估价值是计算房产税所用的数字——它既不是市场价值，也不是挂牌价格。所有金额均为加元。",pr_card_strata:"该地址在公开记录中是一栋有 {n} 个单位的分契式（strata）建筑，各单位的评估价值不同——因此显示的是整栋建筑的价格区间。您自己单位的确切数字请见 BC Assessment（下方链接）。",pr_card_range:"该建筑各单位的评估价值区间",pr_card_src:"来源：温哥华市开放数据（房产税报告及已发建筑许可证）。",pr_permits_title:"近期建筑许可证",pr_permits_none:"在温哥华市开放数据中未找到该地址的许可证。",pr_prop_na:"实时房产记录适用于温哥华的地址。BC 省其他城市请使用下方的官方记录——每处 BC 房产的评估价值都由 BC Assessment 保存。",pr_prop_notfound:"该地址无法在温哥华市开放数据中匹配。请检查地址，或在下方 BC Assessment 查询该房产。",pr_links_title:"官方记录",pr_link_bca:"BC Assessment — 查询任何 BC 房产",pr_link_parcel:"ParcelMap BC — 地块边界与法律描述",pr_link_walkscore:"Walk Score — 该地址的步行便利度",pr_link_ltsa:"LTSA — 土地产权记录与查询",pr_est_title:"它可能值多少钱？",pr_est_body:"评估价值不等于市场价值。可从当前在售的同类房屋免费获得估价区间——就是上方我们卖家使用的同一工具。",pr_est_btn:"估算这套房的价值",pr_gated_note:"有两项内容目前还无法展示。成交价格属于 MLS® 数据，仅限持牌专业人士使用；产权详情（业主、抵押、留置权及其他产权负担）只存在于 LTSA 的产权记录中。以下两个板块均已建成，各板块仅在其数据安排落实后才会启用——在此之前，它们会确切说明缺少什么、官方记录在哪里。",pr_sold_title:"成交历史",pr_sold_gated:"尚不可用。展示成交价格需要牌照及与地产局的数据协议，目前均未落实。",pr_title_title:"产权与留置权查询",pr_title_gated:"尚不可用。产权查询可显示登记业主、抵押、留置权、地役权及房产上的其他负担。通过本网站订购尚未开通——您今天就可以自行向 BC 省土地产权与测量局（LTSA）订购，需支付登记费。",pr_title_btn:"如何获取产权查询",pr_title_sent:"未提交任何订单——本网站的产权查询订购尚未开放。您今天就可以自行向 LTSA 订购查询——产权属于公开记录（见上方官方记录）。",pr_area:"区域",pr_schools_none:"在该区域 10 公里范围内，省级开放数据中未找到学校。",pr_err_city:"请为该地址选择城市。",pr_prop_unavailable:"目前无法加载房产记录。请稍后再试。",pr_prop_ambiguous:"公共记录中有多处房产与此地址匹配，因此为避免猜测，未显示任何一处。您单位或地块的确切记录请见 BC Assessment（下方）。",pr_census_na:"该邮政区域暂无人口普查数据。",pr_schools_unavailable:"目前无法加载学校信息——请稍后再试。",pr_safety_unavailable:"目前无法加载已报告犯罪信息——请稍后再试。",pr_permits_unavailable:"目前无法加载许可证信息——请稍后再试。",pr_card_median:"该建筑各单位的评估价值中位数（{year}）",pr_card_truncated:"该建筑的公共记录过大，无法在此完整读取，因此未显示区间，以免显示不完整的区间。您自己单位的确切数字请见 BC Assessment（下方链接）。",pr_km:"公里",pr_school_other:"其他",pr_approx:"位置匹配为近似值，因此以下数字为最接近匹配区域的数据。",pr_title_placed:"您的产权查询请求已提交。",pr_title_unavailable:"产权查询订购尚未开放——未提交任何订单。您今天就可以自行向 LTSA 订购查询（见上方官方记录）。",pr_render_err:"报告已收到，但无法显示。请重新加载页面后再试一次。",pr_title_err:"产权查询请求未能完成——请重试。",pr_gated_pending:"此板块尚不可用。",pr_privacy:"隐私：您在此输入的内容按以下方式处理。(1) 房屋估价：您的姓名、房产地址、城市、电话、电子邮件以及您提供的房产信息（类型、卧室、浴室、面积）会存储在本网站的客户数据库中，以便 Erfan 为您准备挂牌价格区间并就此与您联系。这些信息会一直保留，直到您要求删除或 Erfan 将其删除，且绝不会出售。如需删除，请通过本页底部的删除表单填写您提交时使用的相同电子邮件和房产地址（或直接联系 Erfan）——删除是永久性的。(2) 房产报告：您输入的邮政编码和地址会被发送到本网站的服务器，服务器会将其提供给公共数据服务（OpenStreetMap 和温哥华市开放数据）以生成报告。您输入的文字不会被保存；为其找到的地图位置会以编码密钥（而非地址本身）缓存长达 30 天，以便重复查询更快。",pr_gated_note_live:"成交价格来自 MLS® 记录,仅供持牌专业人士使用;产权详情(业主、抵押、留置权及其他产权负担)来自 LTSA 的产权记录。以下两个板块为 Erfan 的客户使用这些官方记录。",pr_sold_live:"本房源的成交历史可供 Erfan 的客户查询——请向他索取包含日期和价格的完整 MLS® 成交记录。",pr_title_live:"产权查询可显示登记业主、抵押、留置权、地役权及房产上的其他负担。客户可以通过 Erfan 订购产权查询,也可以直接向 BC 省土地产权与测量局(LTSA)订购,需支付登记费(见官方记录部分)。",pr_city_note:"房产记录适用于温哥华地址；其他城市将获得官方记录链接。"},es:{pr_title:"Informe de propiedad y vecindario",pr_sub:"Ingresa un código postal de BC para obtener una instantánea del vecindario del Censo de {censusYear}, las escuelas más cercanas y — en Vancouver — contexto de delitos reportados. Agrega una dirección completa de Vancouver para ver también el registro público de valuación de la propiedad y los permisos de construcción recientes. Cada sección indica su fuente; las distancias a las escuelas son mediciones aproximadas en línea recta.",pr_jump:"Informe de propiedad y vecindario",pr_jump_sub:"instantánea del censo, escuelas cercanas y el registro público de la propiedad para una dirección de BC.",pr_postal:"Código postal",pr_postal_ph:"ej. V6B 1A1",pr_optional:"(opcional — agrega el registro de la propiedad)",pr_btn:"Crear mi informe",pr_loading:"Creando tu informe…",pr_err:"El informe no pudo crearse en este momento. Inténtalo de nuevo en un momento.",pr_err_rate:"Demasiados informes solicitados — espera un minuto e inténtalo de nuevo.",pr_err_postal:"Ingresa un código postal canadiense válido.",pr_out_area:"Este informe cubre solo British Columbia. El código postal ingresado está fuera de BC, por lo que no se creó ningún informe.",pr_hood_title:"Instantánea del vecindario — {fsa}",pr_src_census:"Fuente: Statistics Canada, {censusYear} Census Profile (forward sortation area {fsa}); el ingreso corresponde a {incomeYear}.",pr_pop:"Población ({censusYear})",pr_dwell:"Viviendas ocupadas",pr_income:"Ingreso familiar mediano ({incomeYear})",pr_hhsize:"Tamaño promedio del hogar",pr_medage:"Edad mediana",pr_age_child:"Residentes menores de 15 años",pr_age_senior:"Residentes de 65 años o más",pr_owner:"Propietarios",pr_renter:"Inquilinos",pr_detached:"Viviendas unifamiliares independientes",pr_eng_home:"Inglés hablado con mayor frecuencia en casa",pr_nonoff_home:"Un idioma no oficial hablado con mayor frecuencia en casa",pr_schools_title:"Escuelas más cercanas",pr_schools_src:"Fuente: datos abiertos del BC Ministry of Education, {schoolYear}. Las distancias son en línea recta desde el centro del área; las zonas escolares las establece el distrito — confirma tu elegibilidad con ellos.",pr_school_e:"Primaria",pr_school_s:"Secundaria",pr_school_m:"Intermedia",pr_school_b:"Primaria y secundaria",pr_school_pub:"Pública",pr_school_ind:"Independiente",pr_safety_title:"Seguridad — delitos reportados",pr_safety_body:"Se reportaron {n} incidentes en {area} en {year} — {total} en los vecindarios listados de Vancouver. Estos son incidentes reportados a la policía, no una calificación de seguridad.",pr_safety_src:"Fuente: datos abiertos del Vancouver Police Department.",pr_safety_na:"Los datos de delitos reportados se publican a nivel de vecindario solo para Vancouver, por lo que no están disponibles para esta área.",pr_card_title:"Registro de la propiedad — {addr}",pr_card_land:"Terreno",pr_card_building:"Edificio",pr_card_total:"Valor total valuado ({year})",pr_card_built:"Año de construcción",pr_card_pid:"PID",pr_card_zoning:"Zonificación",pr_card_levy:"Impuesto predial",pr_card_note:"El valor valuado es la cifra utilizada para los impuestos prediales — no es un valor de mercado ni un precio de venta. Todas las cifras están en dólares canadienses.",pr_card_strata:"Esta dirección es un edificio de strata con {n} unidades en el registro público, y los valores valuados varían por unidad — por lo que se muestra el rango en todo el edificio. La cifra exacta de tu unidad está en BC Assessment (enlace abajo).",pr_card_range:"Valores valuados en las unidades del edificio",pr_card_src:"Fuente: datos abiertos de la City of Vancouver (informe de impuestos prediales y permisos de construcción emitidos).",pr_permits_title:"Permisos de construcción recientes",pr_permits_none:"No se encontraron permisos para esta dirección en los datos abiertos de la City of Vancouver.",pr_prop_na:"Los registros de propiedades en vivo están disponibles para direcciones de Vancouver. Para otras ciudades de BC, usa los registros oficiales a continuación — BC Assessment tiene el valor valuado de cada propiedad de BC.",pr_prop_notfound:"Esta dirección no pudo coincidir en los datos abiertos de la City of Vancouver. Revisa la dirección o busca la propiedad en BC Assessment a continuación.",pr_links_title:"Registros oficiales",pr_link_bca:"BC Assessment — busca cualquier propiedad de BC",pr_link_parcel:"ParcelMap BC — límites de parcelas y descripción legal",pr_link_walkscore:"Walk Score — facilidad para caminar en esta dirección",pr_link_ltsa:"LTSA — registros y búsquedas de títulos de propiedad",pr_est_title:"¿Cuánto podría valer?",pr_est_body:"La valuación no es el valor de mercado. Obtén un rango de estimación gratuito a partir de viviendas comparables actualmente anunciadas — la misma herramienta que usan nuestros vendedores, arriba.",pr_est_btn:"Estimar el valor de esta vivienda",pr_gated_note:"Hay dos cosas que aún no se pueden mostrar. Los precios de venta son datos de MLS®, restringidos a profesionales autorizados; los detalles del título (propietario, hipotecas, gravámenes y otros cargos) se encuentran solo en el registro de título de la LTSA. Ambas secciones a continuación están creadas; cada una estará disponible solo cuando su propio acuerdo de datos esté vigente — hasta entonces indican exactamente qué falta y dónde se encuentra el registro oficial.",pr_sold_title:"Historial de ventas",pr_sold_gated:"Aún no está disponible. Mostrar los precios de venta requiere licencia y un acuerdo de datos con la junta, que aún no están vigentes.",pr_title_title:"Revisión de título y gravámenes",pr_title_gated:"Aún no está disponible. Una búsqueda de título muestra el propietario registrado, hipotecas, gravámenes, servidumbres y otros cargos sobre una propiedad. El pedido a través de este sitio aún no está habilitado — hoy puedes solicitar una búsqueda tú mismo ante la BC Land Title and Survey Authority (LTSA) por una tarifa de registro.",pr_title_btn:"Cómo obtener una búsqueda de título",pr_title_sent:"No se realizó ningún pedido — el pedido de búsquedas de título aún no está disponible en este sitio. Hoy puedes solicitar una búsqueda tú mismo ante la LTSA — un título es un registro público (consulta Registros oficiales arriba).",pr_area:"Área",pr_schools_none:"No se encontraron escuelas en un radio de 10 km de esta área en los datos abiertos provinciales.",pr_err_city:"Elige la ciudad de la dirección.",pr_prop_unavailable:"El registro de la propiedad no pudo cargarse ahora. Inténtalo de nuevo en un momento.",pr_prop_ambiguous:"Más de una propiedad en el registro público coincide con esta dirección, por lo que no se muestra ninguna en lugar de adivinar. BC Assessment (abajo) tiene el registro exacto de tu unidad o lote.",pr_census_na:"Las cifras del censo no están disponibles para esta zona postal.",pr_schools_unavailable:"La información de escuelas no pudo cargarse ahora — inténtalo de nuevo en un momento.",pr_safety_unavailable:"La información de delitos reportados no pudo cargarse ahora — inténtalo de nuevo en un momento.",pr_permits_unavailable:"La información de permisos no pudo cargarse ahora — inténtalo de nuevo en un momento.",pr_card_median:"Valor de tasación mediano entre las unidades del edificio ({year})",pr_card_truncated:"El registro público de este edificio es demasiado grande para leerse completo aquí, por lo que no se muestra ningún rango en lugar de uno parcial. La cifra exacta de tu unidad está en BC Assessment (enlace abajo).",pr_km:"km",pr_school_other:"Otro",pr_approx:"La coincidencia de ubicación es aproximada, por lo que las cifras siguientes corresponden a la zona coincidente más cercana.",pr_title_placed:"Tu solicitud de búsqueda de título ha sido registrada.",pr_title_unavailable:"El pedido de búsquedas de título aún no está disponible — no se realizó ningún pedido. Hoy puedes solicitar una búsqueda por tu cuenta ante la LTSA (consulta Registros oficiales arriba).",pr_render_err:"El informe se recibió pero no pudo mostrarse. Recarga la página e inténtalo de nuevo.",pr_title_err:"La solicitud de búsqueda de título no pudo completarse — inténtalo de nuevo.",pr_gated_pending:"Esta sección aún no está disponible.",pr_privacy:"Privacidad: lo que ingresas aquí se gestiona así. (1) Valoración de vivienda: tu nombre, la dirección de la propiedad, la ciudad, el teléfono, el correo electrónico y los datos de la propiedad que entregas (tipo, dormitorios, baños, superficie) se guardan en la base de datos de contactos de este sitio para que Erfan pueda preparar tu rango de precio de venta y comunicarse contigo al respecto. Se conservan hasta que pidas su eliminación o Erfan los elimine, y nunca se venden. Para eliminarlos, envía el mismo correo electrónico y la misma dirección de propiedad que registraste mediante el formulario de eliminación al final de esta página (o pídeselo directamente a Erfan): la eliminación es permanente. (2) Informe de propiedad: el código postal y la dirección que ingresas se envían al servidor de este sitio, que los pasa a servicios públicos de datos (OpenStreetMap y los datos abiertos de la Ciudad de Vancouver) para crear el informe. El texto que escribes no se guarda; la ubicación en el mapa encontrada para él se guarda en caché, bajo una clave codificada y no la dirección en sí, hasta por 30 días para que las búsquedas repetidas sean más rápidas.",pr_gated_note_live:"Los precios de venta provienen de los registros MLS®, disponibles para profesionales autorizados; los detalles del título (propietario, hipotecas, gravámenes y otros cargos) provienen del registro de títulos de LTSA. Las dos secciones siguientes trabajan con esos registros oficiales para los clientes de Erfan.",pr_sold_live:"El historial de ventas de esta propiedad está disponible para los clientes de Erfan — pídale el registro completo de ventas MLS®, con fechas y precios.",pr_title_live:"Una búsqueda de título muestra el propietario registrado, hipotecas, gravámenes, servidumbres y otros cargos sobre una propiedad. Los clientes pueden encargarla a través de Erfan, o directamente a la Autoridad de Títulos de Tierras y Catastro de BC (LTSA) por una tarifa registral (véase la sección de registros oficiales).",pr_city_note:"El registro de la propiedad cubre direcciones de Vancouver; otras ciudades reciben los enlaces a los registros oficiales."}};
if (window.I18N) { for (var L in window.__PR_I18N) { if (window.I18N[L]) { for (var K in window.__PR_I18N[L]) window.I18N[L][K] = window.__PR_I18N[L][K]; } } }
